#!/bin/sh
# Regenerates the grouper fish cluster charts. Run from the repo root.
K=~/.claude/skills/fishcare-page/scripts; D=assets/guides/grouper; mkdir -p $D
C(){ python3 $K/images.py chart "$@" 2>&1 | grep wrote; }
C --out $D/grouper-fish-care-at-a-glance.svg --title "Grouper fish care at a glance: a predator's numbers" --subtitle "Saltwater only. Big, slow, hardy ambush hunters that eat anything that fits in the mouth." --row "Tank size|75–300+ gallons|by species; 6 ft for most" --row "Temperature|74–80°F (23–27°C)|stable" --row "Salinity|1.023–1.026 SG|reef-standard" --row "pH / nitrate|8.1–8.4 / <30 ppm|heavy filtration, big skimmer" --row "Diet|meaty frozen, 2–3× a week|silversides, shrimp, krill; no live feeders" --row "Tank mates|larger than its mouth|lionfish, triggers, tangs, eels" --row "Lifespan|10–20+ years|slow to mature" --alt "Grouper fish care chart: 75 to 300 gallon tank, 74 to 80 F, 1.023 to 1.026 salinity, pH 8.1 to 8.4, nitrate under 30 ppm, meaty frozen food two to three times a week, tank mates larger than its mouth, 10 to 20 year lifespan" --footer "Each number is expanded on a page of the grouper fish care series."
C --out $D/grouper-fish-tank-size-chart.svg --title "Grouper fish tank size by species" --subtitle "Minimum for one adult. Groupers grow fast and eat the tank mates you sized the tank for." --row "Dwarf: blue-line, V-tail, bluespotted hind|75–100 gal · 4 ft|8–12 in adults" --row "Miniatus / coral hind, leopard hind|100–125 gal · 5–6 ft|12–16 in adults" --row "Panther / humpback grouper|180 gal · 6 ft|20–27 in adults" --row "Bluespotted, lyretail, red grouper|180–300 gal · 6–8 ft|20–30 in adults" --row "Bumblebee, giant, goliath grouper|not for aquariums|3–8 ft adults" --alt "Grouper fish tank size chart: 75 to 100 gallons for dwarf hinds, 100 to 125 gallons for miniatus grouper, 180 gallons for panther grouper, 180 to 300 gallons for bluespotted and lyretail groupers, bumblebee and giant groupers unsuitable" --footer "No grouper suits a nano tank; a 3-inch juvenile is a 12-inch fish in 18 months."
C --out $D/grouper-fish-water-parameters.svg --title "Grouper fish water parameters: reef water with heavy filtration" --subtitle "Groupers are hardy about numbers but produce a huge bioload. Filtration, not chemistry, is the challenge." --row "Temperature|74–80°F (23–27°C)|stable" --row "Salinity|1.023–1.026 SG|33–35 ppt" --row "pH / alkalinity|8.1–8.4 / 8–11 dKH|" --row "Ammonia / nitrite|0 ppm|always" --row "Nitrate|<30 ppm (reef <20)|large weekly changes" --row "Skimmer|rated 2× tank volume|meaty waste" --row "Flow|moderate, with calm caves|ambush predator" --alt "Grouper fish water parameters chart: 74 to 80 F, salinity 1.023 to 1.026, pH 8.1 to 8.4, alkalinity 8 to 11 dKH, zero ammonia and nitrite, nitrate under 30 ppm, skimmer rated twice the tank volume"
C --out $D/grouper-fish-feeding-schedule.svg --title "Grouper fish food and feeding schedule" --subtitle "A gulp feeder. Feed big, feed rarely, and never feed live freshwater fish." --row "Frozen silversides, lancefish|2–3× per week|the staple; whole fish" --row "Frozen shrimp, krill, squid, clam|2–3× per week|variety; thaw and rinse" --row "Large carnivore pellets|weekly, once trained|vitamins; soak first" --row "Vitamin soak (HUFA, C)|every feed|prevents HLLE and fatty liver" --row "Live feeder goldfish / rosy reds|never|thiaminase, fat, disease" --row "Juvenile under 5 in|daily, small pieces|grows fast" --alt "Grouper fish food chart: frozen silversides and lancefish two to three times a week, shrimp krill squid and clam for variety, carnivore pellets weekly, vitamin soak every feed, never live freshwater feeder fish, juveniles fed daily" --footer "A grouper begs constantly. Feed to a slightly rounded belly, then wait two days."
C --out $D/grouper-fish-size-lifespan.svg --title "Grouper fish size and lifespan by species" --subtitle "Aquarium adult length, growth rate and years in a well-run tank." --row "Blue-line / V-tail hind|8–10 in|10–12 years" --row "Miniatus grouper (coral hind)|12–16 in|10–15 years" --row "Leopard hind|12–14 in|10–15 years" --row "Panther / humpback grouper|20–27 in|15–20 years" --row "Bluespotted grouper|20–24 in|15–20 years" --row "Lyretail grouper|24–30 in|15–20 years" --row "Growth rate|6–10 in in year one|slows after 3 years" --alt "Grouper fish size and lifespan chart: blue-line hind 8 to 10 inches, miniatus grouper 12 to 16 inches and 10 to 15 years, panther grouper 20 to 27 inches and 15 to 20 years, lyretail grouper up to 30 inches, growth of 6 to 10 inches in the first year"
C --out $D/grouper-fish-breeding.svg --title "Grouper fish breeding: why it happens in hatcheries, not homes" --subtitle "Protogynous hermaphrodites that spawn in open water. Sexing, spawning and the larval problem." --row "Sex|born female, change to male|largest fish in a group becomes male" --row "Sexing by eye|not possible|size and dominance only" --row "Spawning|dusk, open water, in groups|floating eggs, no care" --row "Eggs|~0.9 mm, hatch in 24 h|carried away by current" --row "Larvae|30–60 days pelagic|need copepods, rotifers" --row "Captive breeding|commercial hatcheries|panther and coral groupers since the 1990s" --alt "Grouper fish breeding chart: born female and change to male, cannot be sexed by eye, spawn at dusk in open water, floating eggs hatch in 24 hours, 30 to 60 day pelagic larvae, bred only in commercial hatcheries" --footer "A pregnant-looking grouper is a well-fed grouper."
C --out $D/grouper-fish-tank-mates.svg --title "Grouper fish tank mates: bigger than the mouth, tougher than the temper" --subtitle "The rule is simple. If it fits in the mouth, it is food; if it is smaller than the grouper, it is bullied." --row "Lionfish, foxface, rabbitfish|✓ excellent|spines keep them off the menu" --row "Large tangs, angels, wrasses|✓ good|fast or big; add before the grouper" --row "Triggers, large puffers|~ with care|may bully a small grouper" --row "Moray eels, snowflake eels|✓ good|classic predator tank" --row "Clownfish, gobies, damsels|✗ food|anything under half the grouper's length" --row "Shrimp, crabs, small fish|✗ food|groupers hunt inverts at night" --row "Another grouper|✗ / 300+ gal|territorial; different genus only" --alt "Grouper fish tank mates chart: lionfish, foxface, large tangs, angels, wrasses and moray eels work; triggers with care; clownfish, gobies, damsels, shrimp and crabs are eaten; a second grouper only in 300 gallons or more"
C --out $D/grouper-fish-behavior.svg --title "Grouper fish behavior: reading a predator" --subtitle "Slow, watchful and surprisingly tame. Most odd behaviour is normal for an ambush hunter." --row "Sitting in a cave all day|normal|ambush position, waiting" --row "Colour change in seconds|normal|mood, camouflage, dominance" --row "Mouth gaping|normal|jaw stretch or a cleaner-fish signal" --row "Barking or thumping sound|normal|territorial call from the swim bladder" --row "Following your hand|normal|learns the feeder; will bite a finger" --row "Hiding and pale for days|stress|new tank, bullying, or illness" --row "Gasping, lying on its side|emergency|oxygen, ammonia or velvet" --alt "Grouper fish behavior chart: sitting in a cave, rapid colour change, mouth gaping, barking sounds and following the keeper are normal; hiding and pale colour for days means stress; gasping or lying on the side is an emergency"
C --out $D/grouper-fish-diseases-chart.svg --title "Grouper fish diseases: the five that reach aquarium groupers" --subtitle "Hardy fish, but wild-caught and big. Quarantine and copper are the tools." --row "Marine ich (Cryptocaryon)|white salt-grain spots|copper 30 days or tank transfer" --row "Marine velvet|gold dust, gasping|copper now; emergency" --row "Flukes|scratching, cloudy eyes|praziquantel, freshwater dip" --row "HLLE|pits around eyes, lateral line|diet, vitamins, water" --row "Fatty liver / bloat|swollen belly, lethargy|stop feeder fish; fast" --row "Cloudy eye / popeye|one eye milky or bulging|water quality, injury; antibiotics" --alt "Grouper fish diseases chart: marine ich white spots, marine velvet gold dust, flukes with scratching and cloudy eyes, HLLE pits, fatty liver and bloat from feeder fish, cloudy eye and popeye from water quality" --footer "Quarantine 4 weeks in a bare tank; a 12-inch grouper with ich in a reef cannot be treated in place."
C --out $D/grouper-fish-tank-size-calculation.svg --title "How the grouper fish tank size calculator works" --subtitle "Adult length sets the base; tank mates and rockwork add to it." --row "1. Species adult size|8 / 14 / 24 in|the fish in 2 years, not today" --row "2. Base tank|75 / 125 / 180–300 gal|and 4 / 6 / 8 ft" --row "3. Large tank mates|+25% each|lionfish, tang, eel" --row "4. Rockwork and caves|+15%|a grouper needs a cave it fits" --row "Result|gallons and length|next standard tank up" --alt "Grouper fish tank size calculator diagram: adult size sets a base of 75, 125 or 180 to 300 gallons and 4, 6 or 8 feet, plus 25 percent per large tank mate and 15 percent for rockwork, rounded to the next standard tank"
C --out $D/grouper-fish-types-chart.svg --title "Types of grouper fish for the aquarium" --subtitle "Three size bands. Only the first two belong in a home tank." --row "Dwarf hinds (8–12 in)|blue-line, V-tail, bluespotted hind|75–100 gal" --row "Medium (12–16 in)|miniatus, leopard hind, harlequin|100–125 gal" --row "Large (20–30 in)|panther, bluespotted, lyretail, red|180–300 gal" --row "Public aquarium only|bumblebee, giant, goliath, Nassau|3–8 ft adults" --row "Best first grouper|miniatus (coral hind)|hardy, colourful, 100 gal" --alt "Types of grouper fish chart: dwarf hinds 8 to 12 inches in 75 to 100 gallons, miniatus and leopard hind 12 to 16 inches in 100 to 125 gallons, panther, bluespotted and lyretail 20 to 30 inches in 180 to 300 gallons, bumblebee and giant groupers for public aquariums only"
